int sendto(int fd, void __user *buff, size_t len, unsigned int flags,
           struct sockaddr __user *addr, int addr_len)
{
    struct socket *sock;
    struct msghdr msg;
    int ret, nonblocking;
    size_t max_len = 0;

    max_len = sysctl_wmem_default;
    if (len > max_len)
        len = max_len;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    nonblocking = sock->file->f_flags & O_NONBLOCK;
    flags = nonblocking ? (flags | MSG_DONTWAIT) : (flags & ~MSG_DONTWAIT);

    memset(&msg, 0, sizeof(msg));
    msg.msg_name = addr;
    msg.msg_namelen = addr_len;
    msg.msg_flags = flags;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_iocb = NULL;
    msg.msg_iter.iov = NULL;
    msg.msg_iter.num_segs = 0;
    msg.msg_iter.type = READ;
    msg.msg_iter.iov = NULL;
    msg.msg_iter.count = len;
    msg.msg_iter.iov_base = buff;

    ret = sock_sendmsg(sock, &msg, len);
    if (ret < 0)
        goto out;

    out:
    sockfd_put(sock);
    return ret;
}

int sendto(int fd, void __user *buff, size_t len, unsigned int flags,
           struct sockaddr __user *addr, int addr_len)
{
    struct socket *sock;
    struct msghdr msg;
    int ret = -EBADF;

    if (len > INT_MAX)
        len = INT_MAX;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    msg.msg_name = NULL;
    msg.msg_namelen = 0;
    msg.msg_flags = flags;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;

    if (addr) {
        struct sockaddr *kaddr;

        kaddr = kmalloc(addr_len, GFP_KERNEL);
        if (!kaddr) {
            ret = -ENOMEM;
            goto out;
        }

        if (copy_from_user(kaddr, addr, addr_len)) {
            ret = -EFAULT;
            kfree(kaddr);
            goto out;
        }

        msg.msg_name = kaddr;
        msg.msg_namelen = addr_len;
    }

    if (sock->file->f_flags & O_NONBLOCK)
        msg.msg_flags |= MSG_DONTWAIT;

    ret = sock_sendmsg(sock, &msg, len);

    if (addr)
        kfree(msg.msg_name);

out:
    sockfd_put(sock);
    return ret;
}

#include <linux/socket.h>
